-- неверно: вернёт пусто
select * from users where deleted_at = null;
-- верно:
select * from users where deleted_at is null;

-- count(*) считает строки, count(email) — не-NULL email
select count(*), count(email) from users;

-- вторая по величине зарплата с учётом дубликатов
with ranked as (
  select salary, dense_rank() over (order by salary desc) as rnk
  from employee
)
select distinct salary from ranked where rnk = 2;

-- топ-3 заказа каждого пользователя, строки не схлопываются
select user_id, id, total
from (
  select user_id, id, total,
         row_number() over (partition by user_id order by total desc) as rn
  from orders
) t
where rn <= 3;

// JPA optimistic locking
@Entity
class Account {
    @Id Long id;
    @Version long version; // проверяется и инкрементируется при UPDATE
    long balance;
}

-- обе транзакции берут строки в одном порядке (по возрастанию id)
begin;
  select * from accounts where id in (:from, :to)
  order by id for update;   -- порядок захвата предсказуем → цикла нет
  update accounts set balance = balance - :amt where id = :from;
  update accounts set balance = balance + :amt where id = :to;
commit;

try (PreparedStatement st = con.prepareStatement(
        "select * from users where email = ?")) {
    st.setString(1, email); // значение, а не часть SQL
    try (ResultSet rs = st.executeQuery()) {
        while (rs.next()) { /* ... */ }
    }
}

con.setAutoCommit(false);
try {
    // несколько операций в одной транзакции
    con.commit();
} catch (SQLException e) {
    con.rollback();
    throw e;
} finally {
    con.setAutoCommit(true);
}

con.setAutoCommit(false);   // в PostgreSQL обязательно для серверного курсора
try (PreparedStatement st = con.prepareStatement("select id, total from orders")) {
    st.setFetchSize(1000);  // тянем порциями, а не весь результат в память
    try (ResultSet rs = st.executeQuery()) {
        while (rs.next()) { /* обрабатываем построчно */ }
    }
}

try (PreparedStatement st = con.prepareStatement(
        "insert into orders(user_id, total) values (?, ?)")) {
    for (Order o : orders) {
        st.setLong(1, o.userId());
        st.setBigDecimal(2, o.total());
        st.addBatch();              // накапливаем
    }
    st.executeBatch();              // одна пачка вместо N round-trips
}

// 1 запрос за заказами + по запросу на orders.getItems() каждой строки
for (Order o : orderRepository.findAll()) {
    total += o.getItems().size(); // lazy → N запросов
}

@Transactional
void renameUser(Long id, String name) {
    User user = repository.findById(id).orElseThrow(); // managed
    user.setName(name);   // dirty checking: UPDATE сгенерируется на flush
}                          // save() вызывать не нужно

-- индекс по email не сработает: функция над колонкой
select * from users where lower(email) = ?;

-- вариант 1: функциональный индекс
create index idx_users_email_lower on users (lower(email));

-- вариант 2: частичный индекс под горячий запрос
create index idx_orders_active on orders (created_at desc)
where status = 'ACTIVE';

create table products (
  id         bigserial primary key,
  sku        text not null unique,        -- предсказуемое → колонка
  price      numeric(12,2) not null,      -- по нему фильтруют → колонка
  attributes jsonb not null default '{}'  -- произвольное → документ
);

-- индекс по содержимому документа
create index idx_products_attrs on products using gin (attributes);
select * from products where attributes @> '{"color": "red"}';

User user = cache.get(id);
if (user == null) {            // cache miss
    user = repository.findById(id);
    cache.set(id, user, ttl);  // заполняем кэш
}
return user;

